-- Sovereign Curriculum — หลักสูตรสร้างยอดคน (โฮมสคูล)
-- สาขาวิชา + บทเรียนที่เรียนได้จริงที่บ้าน + เชื่อมกับบันทึกเรียนจบ + เกียรติบัตรจบสาขา

-- 1) ตารางสาขา
CREATE TABLE "curriculum_tracks" (
    "id" UUID NOT NULL,
    "code" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "description" TEXT,
    "emoji" TEXT NOT NULL DEFAULT '🎓',
    "color" TEXT NOT NULL DEFAULT '#10b981',
    "sort_order" INTEGER NOT NULL DEFAULT 0,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "curriculum_tracks_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "curriculum_tracks_code_key" ON "curriculum_tracks"("code");

-- 2) ตารางบทเรียน (ต่อสาขา)
CREATE TABLE "curriculum_items" (
    "id" UUID NOT NULL,
    "track_id" UUID NOT NULL,
    "title" TEXT NOT NULL,
    "description" TEXT,
    "stage" INTEGER NOT NULL DEFAULT 1,
    "sequence" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "curriculum_items_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "curriculum_items_track_id_fkey" FOREIGN KEY ("track_id") REFERENCES "curriculum_tracks"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "curriculum_items_track_id_sequence_key" ON "curriculum_items"("track_id", "sequence");
CREATE INDEX "curriculum_items_track_id_idx" ON "curriculum_items"("track_id");

-- 3) เชื่อมบันทึกเรียนจบเข้ากับบทเรียนหลักสูตร
ALTER TABLE "kid_lesson_progress" ADD COLUMN "curriculum_item_id" UUID;
CREATE INDEX "kid_lesson_progress_curriculum_item_id_idx" ON "kid_lesson_progress"("curriculum_item_id");
ALTER TABLE "kid_lesson_progress" ADD CONSTRAINT "kid_lesson_progress_curriculum_item_id_fkey" FOREIGN KEY ("curriculum_item_id") REFERENCES "curriculum_items"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- 4) เกียรติบัตร: แยกประเภท level (เลื่อนระดับ) vs subject (จบสาขา)
ALTER TABLE "kid_certificates" ADD COLUMN "kind" TEXT NOT NULL DEFAULT 'level';

-- 5) Seed หลักสูตร 7 สาขา × 6 บทเรียน (สร้างคนอยู่บ้าน)
INSERT INTO "curriculum_tracks" ("id", "code", "title", "description", "emoji", "color", "sort_order") VALUES
  ('00000000-0000-4000-8000-000000000001', 'INNER_OS', 'Inner OS — จัดการใจและตัวเอง', 'ฐานของการเรียนรู้ทั้งหมด: เป้าหมาย ตารางเวลา สมาธิ ความรับผิดชอบ และการทบทวนตัวเอง', '🧠', '#a78bfa', 1),
  ('00000000-0000-4000-8000-000000000002', 'MICRO_ECONOMY', 'Micro-Economy — เงินและเศรษฐกิจที่บ้าน', 'ค่าขนม งานบ้าน บิล กระปุก หุ้นจำลอง — เศรษฐศาสตร์จุลภาคที่เรียนจากเงินจริงของตัวเอง', '💰', '#f59e0b', 2),
  ('00000000-0000-4000-8000-000000000003', 'ENGINEERING', 'Engineering — วิศวกรรมและเทคโนโลยี', 'บ้านคือห้องแล็บ: ไฟฟ้า แบตเตอรี่ เซนเซอร์ ระบบน้ำ relay และการซ่อมของจริง', '⚙️', '#22d3ee', 3),
  ('00000000-0000-4000-8000-000000000004', 'BIO_OPTIMIZATION', 'Bio-Optimization — ร่างกายและสุขภาพ', 'อาหาร การนอน การออกกำลัง การสังเกตสุขภาพของตัวเองในวงจรชีวิตจริง', '🌱', '#10b981', 4),
  ('00000000-0000-4000-8000-000000000005', 'DEFENSE', 'Defense & Tactics — การป้องกันและความมั่นคง', 'หนีไฟ รับมือน้ำท่วม ฉุกเฉิน ไซเบอร์ ความปลอดภัย — อยู่บ้านต้องพร้อมเสมอ', '🛡️', '#ef4444', 5),
  ('00000000-0000-4000-8000-000000000006', 'SOCIAL_POWER', 'Social & Power — สังคมและครอบครัว', 'กติกา การขอและต่อรอง ความกตัญญู ประวัติศาสตร์ครอบครัว และการอยู่ร่วมกัน', '🤝', '#f472b6', 6),
  ('00000000-0000-4000-8000-000000000007', 'ACADEMIC', 'Academic Core — ภาษา คณิต วิทยาศาสตร์', 'วิชาพื้นฐานที่เรียนได้ที่บ้าน: อ่านเขียนเลขและทดลองวิทยาศาสตร์จากสิ่งรอบตัว', '📚', '#60a5fa', 7);

